params.css:
#sheet{column-count:2;column-gap:7mm;column-rule:.3mm solid #b9c4cd;}
#sheet .inner{column-count:2;column-gap:7mm;column-rule:.3mm solid #b9c4cd;}
#sheet main{column-count:2;column-gap:7mm;column-rule:.3mm solid #b9c4cd;}
#sheet .frame{column-count:2;column-gap:7mm;column-rule:.3mm solid #b9c4cd;}
#sheet .card{column-count:2;column-gap:7mm;column-rule:.3mm solid #b9c4cd;}
#sheet > *{break-inside:avoid;margin-bottom:1mm;width:auto;max-width:none;}
#sheet .inner > *{break-inside:avoid;margin-bottom:1mm;width:auto;max-width:none;}
#sheet main > *{break-inside:avoid;margin-bottom:1mm;width:auto;max-width:none;}
#sheet .frame > *{break-inside:avoid;margin-bottom:1mm;width:auto;max-width:none;}
#sheet .card > *{break-inside:avoid;margin-bottom:1mm;width:auto;max-width:none;}
#sheet > *:first-child:not(.frame):not(.card):not(.inner){column-span:all;border-bottom:.5mm solid #1d3b5c;margin-bottom:2mm;}
#sheet .inner > *:first-child:not(.frame):not(.card):not(.inner){column-span:all;border-bottom:.5mm solid #1d3b5c;margin-bottom:2mm;}
#sheet main > *:first-child:not(.frame):not(.card):not(.inner){column-span:all;border-bottom:.5mm solid #1d3b5c;margin-bottom:2mm;}
#sheet .frame > *:first-child:not(.frame):not(.card):not(.inner){column-span:all;border-bottom:.5mm solid #1d3b5c;margin-bottom:2mm;}
#sheet .card > *:first-child:not(.frame):not(.card):not(.inner){column-span:all;border-bottom:.5mm solid #1d3b5c;margin-bottom:2mm;}
#sheet .frame, #sheet .inner{border:0;}
#sheet .inner .frame, #sheet .inner{border:0;}
#sheet main .frame, #sheet .inner{border:0;}
#sheet .frame .frame, #sheet .inner{border:0;}
#sheet .card .frame, #sheet .inner{border:0;}
#sheet{font-family:'DejaVuSans','LiberationSans','DejaVu Sans',sans-serif;}
#sheet table.items th{background:#1d3b5c;color:#fff;border:0;}
#sheet .inner table.items th{background:#1d3b5c;color:#fff;border:0;}
#sheet main table.items th{background:#1d3b5c;color:#fff;border:0;}
#sheet .frame table.items th{background:#1d3b5c;color:#fff;border:0;}
#sheet .card table.items th{background:#1d3b5c;color:#fff;border:0;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet table.items{table-layout:fixed;}
#sheet .inner table.items{table-layout:fixed;}
#sheet main table.items{table-layout:fixed;}
#sheet .frame table.items{table-layout:fixed;}
#sheet .card table.items{table-layout:fixed;}
#sheet table.items th{overflow-wrap:anywhere;}
#sheet .inner table.items th{overflow-wrap:anywhere;}
#sheet main table.items th{overflow-wrap:anywhere;}
#sheet .frame table.items th{overflow-wrap:anywhere;}
#sheet .card table.items th{overflow-wrap:anywhere;}
#sheet table.items td{overflow-wrap:anywhere;}
#sheet .inner table.items td{overflow-wrap:anywhere;}
#sheet main table.items td{overflow-wrap:anywhere;}
#sheet .frame table.items td{overflow-wrap:anywhere;}
#sheet .card table.items td{overflow-wrap:anywhere;}
#sheet > .frame,#sheet .frame > .frame,#sheet > .card,#sheet .frame > .card,#sheet > .inner,#sheet .frame > .inner{margin-left:0;margin-right:0;background:transparent;color:inherit;}
